static TestProc init_repo(const char*r){const char*a[]={"./darc","init",r,NULL};return test_exec(a,NULL);}
static TestProc snap(const char*r,const char*s,const char*ts,const char*parent,const char*cfg,bool json){const char*a[16];int n=0;a[n++]="./darc";a[n++]="--repo";a[n++]=r;if(cfg){a[n++]="--config";a[n++]=cfg;}if(json){a[n++]="--format";a[n++]="json";}a[n++]="snapshot";a[n++]="create";a[n++]=s;if(parent){a[n++]="--parent";a[n++]=parent;}a[n++]="--timestamp";a[n++]=ts;a[n]=NULL;return test_exec(a,NULL);}
static TestProc diffp(const char*r,const char*a0,const char*b0,const char*fmt){const char*a[]={"./darc","--repo",r,"snapshot","diff",a0,b0,"--format",fmt,NULL};return test_exec(a,NULL);}
static bool load_flat(const char*r,const char*sel,DarcFlatTree*ft,DarcSnapshotObj*so,DarcCid*id){memset(ft,0,sizeof* ft);memset(so,0,sizeof*so);return darc_resolve_snapshot(r,sel,id,so)==0&&darc_flatten_snapshot(r,so,ft)==0;}
static bool load_file(const char*r,const DarcCid*c,DarcFileObj*f){DarcObject o;if(darc_object_load(r,c,&o,1))return false;bool ok=o.type==OBJ_FILE&&!darc_file_parse(o.payload.data,o.payload.len,f);darc_object_free(&o);return ok;}
static uint64_t reused_bytes(const DarcFileObj*a,const DarcFileObj*b){bool*used=calloc(a->chunk_n?a->chunk_n:1,sizeof*used);uint64_t z=0;if(!used)return 0;for(size_t j=0;j<b->chunk_n;j++)for(size_t i=0;i<a->chunk_n;i++)if(!used[i]&&a->chunks[i].len==b->chunks[j].len&&darc_cid_eq(&a->chunks[i].cid,&b->chunks[j].cid)){used[i]=true;z+=b->chunks[j].len;break;}free(used);return z;}
static bool make_pattern(const char*p,size_t n){int fd=open(p,O_CREAT|O_TRUNC|O_WRONLY|O_CLOEXEC,0644);if(fd<0)return false;uint8_t b[65536];size_t off=0;while(off<n){size_t z=n-off<sizeof b?n-off:sizeof b;for(size_t i=0;i<z;i++)b[i]=(uint8_t)(((off+i)*1315423911u>>17)^((off+i)*29u)^((off+i)>>7));if(darc_write_all(fd,b,z)){close(fd);return false;}off+=z;}return close(fd)==0;}
static char *cfg_disabled(const char*d){char*p=test_path(d,"no-compress.json");if(p)test_write(p,"{\"compression\":{\"enabled\":false}}\n",34,0644);return p;}
static size_t count_refs(const char*r){char*p=test_path(r,"refs/snapshots");DIR*d=p?opendir(p):NULL;size_t n=0;if(d){struct dirent*e;while((e=readdir(d)))if(e->d_name[0]!='.')n++;closedir(d);}free(p);return n;}
static bool flip_object(const char*r,const DarcCid*c,uint8_t*xorv){char*p=darc_object_path(r,c);if(!p)return false;int fd=open(p,O_RDWR|O_CLOEXEC);if(fd<0){free(p);return false;}struct stat st;bool ok=!fstat(fd,&st)&&st.st_size>40;if(ok){off_t at=st.st_size-1;uint8_t b;if(pread(fd,&b,1,at)!=1)ok=false;else{b^=*xorv;if(pwrite(fd,&b,1,at)!=1||fsync(fd))ok=false;}}close(fd);free(p);return ok;}
static bool set_ns(const char*p,time_t sec){struct timespec t[2]={{sec,0},{sec,0}};return utimensat(AT_FDCWD,p,t,AT_SYMLINK_NOFOLLOW)==0;}

